insert into public.products (id, slug, name, category_id, short_description, full_description, images, tags, featured, enabled_for_sale, sort_order) values ('ginger-shot', 'ginger-shot', 'Ginger Shot', 'wellness-shots', 'A warming, zesty ginger blend for your daily wellness routine.', array['Our Ginger Shot is bold by design: a warming, zesty hit of ginger made to be the easiest part of your morning.', 'Keep one in the fridge, take it with breakfast or before you head out, and let the flavour wake you up.']::text[], '[{"src":"/images/products/ginger-shot.webp","alt":"Ginger Shot bottle with its Naturo Wellness label","placeholder":false,"width":900,"height":1350}]'::jsonb, array['daily-routine', 'citrus', 'warming', 'bestseller-candidate']::text[], true, true, 0) on conflict (id) do nothing;
