insert into public.products (id, slug, name, category_id, short_description, full_description, images, tags, featured, enabled_for_sale, sort_order) values ('hibiscus-shot', 'hibiscus-shot', 'Hibiscus Shot', 'wellness-shots', 'A tangy, refreshing hibiscus blend with a vibrant botanical character.', array['Deep ruby in colour and tangy on the tongue, our Hibiscus Shot celebrates one of the most striking flowers in the botanical world.', 'Refreshing on its own, chilled, or as a bright moment in your day.']::text[], '[{"src":"/images/products/hibiscus-shot.webp","alt":"Hibiscus Shot bottle with its Naturo Wellness label","placeholder":false,"width":900,"height":1350}]'::jsonb, array['botanical', 'tangy', 'floral']::text[], true, true, 2) on conflict (id) do nothing;
